public class Person
{
    public string Name;
    public int Age;

    // Default values
    public Person() : this("Unknown", 0) { }

    // Full initialization
    public Person(string name, int age)
    {
        Name = name;
        Age = age;
    }
}

var p = new Person();
Console.WriteLine(p.Name); // Unknown

public class Animal
{
    public string Name;
    public Animal(string name) { Name = name; }
}

public class Dog : Animal
{
    public string Breed;
    public Dog(string name, string breed) : base(name)
    {
        Breed = breed;
    }
}

var d = new Dog("Rex", "Lab");

